-- ROTL_MANAGER — Initial PostgreSQL schema
-- PostgreSQL 15+ recommended. UUIDs are generated by gen_random_uuid().
CREATE TABLE currencies (
  code CHAR(3) PRIMARY KEY,
  name VARCHAR(40) NOT NULL,
  symbol VARCHAR(8) NOT NULL,
  is_active BOOLEAN NOT NULL DEFAULT TRUE
);
INSERT INTO currencies(code, name, symbol) VALUES ('CDF', 'Franc congolais', 'FC'), ('USD', 'Dollar américain', '$');

CREATE TABLE companies (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(160) NOT NULL, legal_name VARCHAR(200),
  timezone VARCHAR(60) NOT NULL DEFAULT 'Africa/Lubumbashi', is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE company_currencies (
  company_id UUID NOT NULL REFERENCES companies(id), currency_code CHAR(3) NOT NULL REFERENCES currencies(code),
  is_enabled BOOLEAN NOT NULL DEFAULT TRUE, is_default BOOLEAN NOT NULL DEFAULT FALSE,
  PRIMARY KEY(company_id, currency_code)
);
CREATE UNIQUE INDEX uq_company_default_currency ON company_currencies(company_id) WHERE is_default = TRUE;

CREATE TABLE stores (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES companies(id),
  code VARCHAR(30) NOT NULL, name VARCHAR(120) NOT NULL, address TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id, code), UNIQUE(id, company_id)
);
CREATE TABLE cash_registers (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), store_id UUID NOT NULL REFERENCES stores(id),
  code VARCHAR(30) NOT NULL, name VARCHAR(100) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE,
  UNIQUE(store_id, code), UNIQUE(id, store_id)
);

CREATE TABLE users (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES companies(id),
  first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, email VARCHAR(190), phone VARCHAR(30),
  password_hash VARCHAR(255), status VARCHAR(20) NOT NULL DEFAULT 'PENDING'
    CHECK (status IN ('PENDING','ACTIVE','SUSPENDED','REJECTED')),
  last_login_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(company_id, email), UNIQUE(company_id, phone)
);
CREATE TABLE roles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, scope VARCHAR(20) NOT NULL CHECK (scope IN ('GLOBAL','STORE')));
CREATE TABLE permissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code VARCHAR(100) NOT NULL UNIQUE, description TEXT);
CREATE TABLE role_permissions (role_id UUID NOT NULL REFERENCES roles(id), permission_id UUID NOT NULL REFERENCES permissions(id), PRIMARY KEY(role_id, permission_id));
CREATE TABLE user_roles (user_id UUID NOT NULL REFERENCES users(id), role_id UUID NOT NULL REFERENCES roles(id), store_id UUID REFERENCES stores(id), PRIMARY KEY(user_id, role_id, store_id));
CREATE TABLE account_requests (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES companies(id),
  requested_identity JSONB NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','APPROVED','REJECTED')),
  reviewed_by UUID REFERENCES users(id), reviewed_at TIMESTAMPTZ, decision_note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE categories (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES companies(id),
  parent_id UUID REFERENCES categories(id), name VARCHAR(120) NOT NULL, description TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE,
  UNIQUE(company_id, name), UNIQUE(id, company_id)
);
CREATE TABLE products (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES companies(id),
  category_id UUID, sku VARCHAR(60) NOT NULL, barcode VARCHAR(100), name VARCHAR(180) NOT NULL,
  description TEXT, unit VARCHAR(20) NOT NULL DEFAULT 'UNIT', image_uri TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(company_id, sku), UNIQUE(id, company_id),
  FOREIGN KEY(category_id, company_id) REFERENCES categories(id, company_id)
);
CREATE UNIQUE INDEX uq_products_company_barcode ON products(company_id, barcode) WHERE barcode IS NOT NULL;
CREATE TABLE product_prices (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID NOT NULL REFERENCES products(id),
  currency_code CHAR(3) NOT NULL REFERENCES currencies(code),
  purchase_price NUMERIC(19,4) NOT NULL CHECK (purchase_price >= 0),
  selling_price NUMERIC(19,4) NOT NULL CHECK (selling_price >= 0),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(product_id, currency_code)
);

CREATE TABLE stocks (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), store_id UUID NOT NULL REFERENCES stores(id),
  product_id UUID NOT NULL REFERENCES products(id), quantity_on_hand NUMERIC(19,3) NOT NULL DEFAULT 0,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(store_id, product_id), CHECK (quantity_on_hand >= 0)
);
CREATE TABLE stock_movements (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), store_id UUID NOT NULL REFERENCES stores(id),
  product_id UUID NOT NULL REFERENCES products(id), movement_type VARCHAR(30) NOT NULL,
  quantity_delta NUMERIC(19,3) NOT NULL CHECK (quantity_delta <> 0), reference_type VARCHAR(40), reference_id UUID,
  created_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), reason TEXT
);
CREATE INDEX ix_stock_movements_product_date ON stock_movements(store_id, product_id, created_at DESC);
CREATE TABLE stock_adjustments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), store_id UUID NOT NULL REFERENCES stores(id),
  status VARCHAR(20) NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','VALIDATED','CANCELLED')),
  reason TEXT NOT NULL, created_by UUID NOT NULL REFERENCES users(id), validated_by UUID REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(), validated_at TIMESTAMPTZ
);
CREATE TABLE stock_adjustment_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), adjustment_id UUID NOT NULL REFERENCES stock_adjustments(id),
  product_id UUID NOT NULL REFERENCES products(id), system_quantity NUMERIC(19,3) NOT NULL,
  counted_quantity NUMERIC(19,3) NOT NULL CHECK (counted_quantity >= 0), difference NUMERIC(19,3) NOT NULL,
  UNIQUE(adjustment_id, product_id)
);

CREATE TABLE cash_sessions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), cash_register_id UUID NOT NULL REFERENCES cash_registers(id),
  opened_by UUID NOT NULL REFERENCES users(id), opened_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  closed_by UUID REFERENCES users(id), closed_at TIMESTAMPTZ, status VARCHAR(20) NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','CLOSED')),
  closing_note TEXT
);
CREATE UNIQUE INDEX uq_cash_session_open_register ON cash_sessions(cash_register_id) WHERE status = 'OPEN';
CREATE TABLE cash_session_balances (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), cash_session_id UUID NOT NULL REFERENCES cash_sessions(id),
  currency_code CHAR(3) NOT NULL REFERENCES currencies(code), opening_amount NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK (opening_amount >= 0),
  closing_amount_declared NUMERIC(19,4), closing_amount_expected NUMERIC(19,4),
  UNIQUE(cash_session_id, currency_code),
  CHECK (closing_amount_declared IS NULL OR closing_amount_declared >= 0),
  CHECK (closing_amount_expected IS NULL OR closing_amount_expected >= 0)
);

CREATE TABLE sales (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES companies(id),
  store_id UUID NOT NULL REFERENCES stores(id), cash_register_id UUID NOT NULL REFERENCES cash_registers(id),
  cash_session_id UUID NOT NULL REFERENCES cash_sessions(id), sale_number VARCHAR(50) NOT NULL,
  currency_code CHAR(3) NOT NULL REFERENCES currencies(code), status VARCHAR(20) NOT NULL DEFAULT 'DRAFT'
    CHECK (status IN ('DRAFT','VALIDATED','CANCELLED')),
  subtotal NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK (subtotal >= 0), discount_total NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK (discount_total >= 0),
  tax_total NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK (tax_total >= 0), total NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK (total >= 0),
  created_by UUID NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  validated_at TIMESTAMPTZ, cancellation_reason TEXT, UNIQUE(company_id, sale_number)
);
CREATE INDEX ix_sales_store_created ON sales(store_id, created_at DESC);
CREATE TABLE sale_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sale_id UUID NOT NULL REFERENCES sales(id),
  product_id UUID NOT NULL REFERENCES products(id), product_name_snapshot VARCHAR(180) NOT NULL, sku_snapshot VARCHAR(60) NOT NULL,
  quantity NUMERIC(19,3) NOT NULL CHECK (quantity > 0), unit_price NUMERIC(19,4) NOT NULL CHECK (unit_price >= 0),
  discount_amount NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK (discount_amount >= 0), line_total NUMERIC(19,4) NOT NULL CHECK (line_total >= 0)
);
CREATE TABLE payments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sale_id UUID NOT NULL REFERENCES sales(id),
  payment_method VARCHAR(30) NOT NULL, currency_code CHAR(3) NOT NULL REFERENCES currencies(code),
  amount NUMERIC(19,4) NOT NULL CHECK (amount > 0), sale_currency_amount NUMERIC(19,4) NOT NULL CHECK (sale_currency_amount > 0),
  exchange_rate NUMERIC(19,8), reference VARCHAR(120), paid_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK ((exchange_rate IS NULL AND currency_code = (SELECT currency_code FROM sales WHERE sales.id = sale_id)) OR exchange_rate > 0)
);
CREATE TABLE cash_movements (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), cash_session_id UUID NOT NULL REFERENCES cash_sessions(id),
  movement_type VARCHAR(20) NOT NULL CHECK (movement_type IN ('CASH_IN','CASH_OUT')),
  currency_code CHAR(3) NOT NULL REFERENCES currencies(code), amount NUMERIC(19,4) NOT NULL CHECK (amount > 0),
  reason TEXT NOT NULL, reference_type VARCHAR(40), reference_id UUID, created_by UUID NOT NULL REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sale_id UUID NOT NULL REFERENCES sales(id), invoice_number VARCHAR(60) NOT NULL UNIQUE, issued_at TIMESTAMPTZ NOT NULL DEFAULT now(), status VARCHAR(20) NOT NULL DEFAULT 'ISSUED');
CREATE TABLE receipts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sale_id UUID NOT NULL REFERENCES sales(id), receipt_number VARCHAR(60) NOT NULL UNIQUE, issued_at TIMESTAMPTZ NOT NULL DEFAULT now(), document_uri TEXT);
CREATE TABLE audit_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES companies(id), store_id UUID REFERENCES stores(id),
  actor_user_id UUID REFERENCES users(id), action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id UUID,
  before_data JSONB, after_data JSONB, ip_address INET, created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ix_audit_logs_company_date ON audit_logs(company_id, created_at DESC);

-- Seed role catalog; permission assignments are managed by application migrations/configuration.
